  const concreteBody = "\n<div class=\"article-container\" style=\"max-width:1040px;margin:0 auto;padding:1.5rem 1rem;\">\n  <div style=\"margin-bottom:2rem;border-bottom:1px solid var(--border);padding-bottom:1.5rem;\">\n    <div style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.85rem;color:var(--text-muted);margin-bottom:0.5rem;\">\n      <a href=\"/\" style=\"color:inherit;text-decoration:none;\">Home</a> &gt; <a href=\"/calc/\" style=\"color:inherit;text-decoration:none;\">Trade & Construction</a> &gt; <span>Concrete Calculator</span>\n    </div>\n    <h1 style=\"font-family:var(--serif);font-size:2.3rem;margin-bottom:0.75rem;line-height:1.2;\">Concrete Slab, Footing & Bag Calculator</h1>\n    <p style=\"color:var(--text-muted);font-size:1.05rem;line-height:1.6;margin:0;\">\n      Calculate cubic yards, cubic feet, and exact pre-mix bag counts (80 lb, 60 lb, 50 lb) for concrete slabs, patios, footings, and cylindrical sonotubes. Features automatic waste factor budgeting, gravel sub-base estimation, and ready-mix truck delivery cost comparisons.\n    </p>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(320px, 1fr));gap:2rem;margin-bottom:2.5rem;\">\n    <!-- INPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n      <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:1.25rem;display:flex;align-items:center;gap:0.5rem;\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18M9 21V9\"/></svg>\n        Structure Dimensions\n      </h2>\n\n      <div style=\"margin-bottom:1.25rem;\">\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"structureType\">Project Structure Type</label>\n        <select id=\"structureType\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n          <option value=\"slab\" selected>Rectangular Slab / Patio / Driveway</option>\n          <option value=\"column\">Round Column / Pier / Sonotube Footing</option>\n          <option value=\"curb\">Continuous Wall / Curb / Trench Footing</option>\n        </select>\n      </div>\n\n      <!-- RECTANGULAR SLAB INPUTS -->\n      <div id=\"slabInputs\">\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"slabLength\">Length (Feet)</label>\n            <input type=\"number\" id=\"slabLength\" value=\"20\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"slabWidth\">Width (Feet)</label>\n            <input type=\"number\" id=\"slabWidth\" value=\"12\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n        </div>\n\n        <div style=\"margin-bottom:1.25rem;\">\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"slabThickness\">Slab Thickness (Inches)</label>\n          <select id=\"slabThickness\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"3.5\">3.5\" (Standard 2x4 Form Board — Sidewalks/Walkways)</option>\n            <option value=\"4\" selected>4.0\" (Standard Residential Patio / Shed Slab)</option>\n            <option value=\"5\">5.0\" (Light Vehicle Driveway / Heavy Shed)</option>\n            <option value=\"6\">6.0\" (Standard Vehicle Driveway / Garage Floor)</option>\n            <option value=\"8\">8.0\" (Heavy Truck / RV Parking Pad / Foundation)</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- CYLINDER SONOTUBE INPUTS (HIDDEN INITIALLY) -->\n      <div id=\"columnInputs\" style=\"display:none;\">\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"colDiameter\">Diameter (Inches)</label>\n            <select id=\"colDiameter\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n              <option value=\"8\">8\" (Deck Post Pier)</option>\n              <option value=\"10\">10\" (Standard Deck Footing)</option>\n              <option value=\"12\" selected>12\" (Heavy Deck / Structural Pier)</option>\n              <option value=\"16\">16\" (Large Column / Commercial)</option>\n            </select>\n          </div>\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"colDepth\">Depth (Inches)</label>\n            <input type=\"number\" id=\"colDepth\" value=\"36\" min=\"6\" step=\"6\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n        </div>\n\n        <div style=\"margin-bottom:1.25rem;\">\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"colCount\">Number of Columns / Holes</label>\n          <input type=\"number\" id=\"colCount\" value=\"6\" min=\"1\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n      </div>\n\n      <!-- WASTE & CONTROLS -->\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wasteFactor\">Waste Allowance (%)</label>\n          <select id=\"wasteFactor\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"5\">5% (Precise Wooden Forms)</option>\n            <option value=\"10\" selected>10% (Recommended Standard)</option>\n            <option value=\"15\">15% (Rough Grade / Deep Dig)</option>\n          </select>\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"bagPrice80\">Price / 80lb Bag ($)</label>\n          <input type=\"number\" id=\"bagPrice80\" value=\"6.50\" min=\"0\" step=\"0.25\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n      </div>\n    </div>\n\n    <!-- SUMMARY & OUTPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);display:flex;flex-direction:column;justify-content:space-between;\">\n      <div>\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;\">\n          <h2 style=\"font-size:1.25rem;margin:0;display:flex;align-items:center;gap:0.5rem;\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n            Material Estimate\n          </h2>\n          <button id=\"copyConcreteBtn\" style=\"padding:0.4rem 0.75rem;font-size:0.8rem;background:var(--bg);border:1px solid var(--border);border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;gap:0.35rem;font-family:var(--sans);\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            <span>Copy Order Sheet</span>\n          </button>\n        </div>\n\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.5rem;\">\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Cubic Yards (yd³)</span>\n            <span id=\"concreteCuYds\" style=\"font-family:var(--mono);font-size:1.9rem;font-weight:800;color:var(--fg);display:block;\">0.00</span>\n            <span id=\"concreteCuFt\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">0.0 cu ft | 0.0 m³</span>\n          </div>\n\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Standard 80 lb Bags</span>\n            <span id=\"bags80Count\" style=\"font-family:var(--mono);font-size:1.9rem;font-weight:800;color:#3b82f6;display:block;\">0</span>\n            <span id=\"estCostBags\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">Est. Cost: $0</span>\n          </div>\n        </div>\n\n        <!-- BAG COMPARISON ROW -->\n        <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;margin-bottom:1.5rem;\">\n          <div style=\"font-size:0.8rem;font-weight:600;color:var(--text-muted);margin-bottom:0.75rem;text-transform:uppercase;letter-spacing:0.05em;\">Alternative Pre-Mix Bag Sizes</div>\n          <div style=\"display:grid;grid-template-columns:repeat(3, 1fr);gap:0.5rem;text-align:center;\">\n            <div style=\"border-right:1px solid var(--border);padding:0 0.25rem;\">\n              <span style=\"font-size:0.72rem;color:var(--text-muted);display:block;\">60 lb Bags</span>\n              <strong id=\"bags60Count\" style=\"font-family:var(--mono);font-size:1.1rem;color:var(--fg);\">0</strong>\n              <span style=\"font-size:0.68rem;color:var(--text-muted);display:block;\">(0.45 cu ft)</span>\n            </div>\n            <div style=\"border-right:1px solid var(--border);padding:0 0.25rem;\">\n              <span style=\"font-size:0.72rem;color:var(--text-muted);display:block;\">50 lb Bags</span>\n              <strong id=\"bags50Count\" style=\"font-family:var(--mono);font-size:1.1rem;color:var(--fg);\">0</strong>\n              <span style=\"font-size:0.68rem;color:var(--text-muted);display:block;\">(0.375 cu ft)</span>\n            </div>\n            <div style=\"padding:0 0.25rem;\">\n              <span style=\"font-size:0.72rem;color:var(--text-muted);display:block;\">40 lb Bags</span>\n              <strong id=\"bags40Count\" style=\"font-family:var(--mono);font-size:1.1rem;color:var(--fg);\">0</strong>\n              <span style=\"font-size:0.68rem;color:var(--text-muted);display:block;\">(0.30 cu ft)</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- LOGISTICS ADVISORY -->\n        <div id=\"truckAdvisoryBox\" style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:0.85rem 1rem;font-size:0.85rem;line-height:1.5;\">\n          <!-- Populated by JS -->\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- INTERACTIVE PERSPECTIVE SVG DIAGRAM -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n    <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:0.5rem;\">Slab & Subgrade Cross-Section Schematic</h2>\n    <p style=\"color:var(--text-muted);font-size:0.9rem;margin-bottom:1.5rem;\">\n      Isometric elevation showing concrete pour thickness, reinforced welded wire / rebar depth, and recommended 4-inch compacted crushed stone base.\n    </p>\n\n    <div style=\"overflow-x:auto;\">\n      <svg id=\"concreteCrossSectionSvg\" viewBox=\"0 0 800 200\" style=\"width:100%;height:auto;min-width:550px;font-family:var(--mono);\"></svg>\n    </div>\n  </div>\n\n  <!-- MATHEMATICAL & ENGINEERING DERIVATIONS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1rem;font-family:var(--serif);\">Concrete Engineering Formulas & Unit Derivations</h2>\n    <p style=\"color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1rem;\">\n      Concrete volume calculations rely on 3D geometric integrations converted from linear inches and feet into standard American volumetric units ($1 \\text{ cubic yard} = 27 \\text{ cubic feet} = 46,656 \\text{ cubic inches}$).\n    </p>\n\n    <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;font-family:var(--mono);font-size:0.85rem;line-height:1.7;overflow-x:auto;\">\n      <strong>1. Rectangular Slab Volume:</strong><br>\n      V_{\\text{slab}} = \\frac{L_{\\text{ft}} \\times W_{\\text{ft}} \\times (T_{\\text{in}} / 12)}{27} \\times (1 + \\frac{\\text{Waste}_{\\%}}{100}) \\quad [\\text{yd}^3]<br><br>\n      <strong>2. Cylindrical Pier / Sonotube Volume:</strong><br>\n      V_{\\text{cyl}} = \\left( \\frac{\\pi \\times (D_{\\text{in}} / 24)^2 \\times (H_{\\text{in}} / 12)}{27} \\right) \\times N_{\\text{columns}} \\times (1 + \\frac{\\text{Waste}_{\\%}}{100}) \\quad [\\text{yd}^3]<br><br>\n      <strong>3. Pre-Mix Bag Equivalency:</strong><br>\n      \\text{Bags}_{80\\text{lb}} = \\frac{V_{\\text{cu ft}}}{0.60 \\text{ ft}^3/\\text{bag}}, \\quad \\text{Bags}_{60\\text{lb}} = \\frac{V_{\\text{cu ft}}}{0.45 \\text{ ft}^3/\\text{bag}}<br><br>\n      <strong>4. Water-Cement Ratio & Compressive Strength:</strong><br>\n      \\text{w/c Ratio} = \\frac{\\text{Weight of Water}}{\\text{Weight of Cementitious Material}} \\approx 0.40 - 0.45 \\quad (\\text{Target: } 4,000 \\text{ PSI})\n    </div>\n  </div>\n\n  <!-- 5 CRITICAL CONCRETE TRAPS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1.25rem;font-family:var(--serif);\">5 Critical Concrete & Foundation Pitfalls</h2>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.25rem;\">\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">1. Adding Excessive Water to the Mix</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Adding extra water to make concrete \"flow easily\" into forms destroys compressive strength. Every extra gallon of water per bag reduces ultimate compressive strength by up to 1,000 PSI, causes massive surface dusting, and guarantees severe shrinkage cracks.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">2. Uncompacted Subgrade & Frost Heave Settling</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Pouring concrete directly onto uncompacted native dirt or clay causes uneven settling within 12 months. All outdoor slabs require a minimum 4-inch base of crushed gravel (such as 3/4\" crushed stone or road base), compacted mechanically with a plate compactor.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">3. Missing or Delayed Control Joints</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Concrete naturally shrinks as moisture evaporates during curing. To prevent wild random cracks, control joints must be grooved to a depth of 1/4 the slab thickness within 12-18 hours of pouring. Spacing must never exceed 2.5x to 3x thickness in feet (e.g. 10 ft max for a 4\" slab).\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">4. Premature Drying & Curing Neglect</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Concrete does not \"dry\" to gain strength; it chemically hydrates. If surface moisture evaporates in direct sun or high wind during the first 7 days, the hydration reaction halts permanently, costing up to 50% of structural strength. Keep slabs damp or apply a curing compound.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">5. Cold Joint Delamination Between Batches</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Mixing 80+ bags by hand takes hours. If batch #1 begins initial set before batch #10 is poured adjacent to it, the two pours will not chemically fuse, creating a weak structural seam called a \"cold joint\" that will leak water and crack under freeze-thaw cycles.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT ENGINE -->\n  <script>\n    (function() {\n      function calcConcrete() {\n        var type = document.getElementById('structureType').value;\n        var waste = (parseFloat(document.getElementById('wasteFactor').value) || 0) / 100;\n        var bagPrice = parseFloat(document.getElementById('bagPrice80').value) || 0;\n\n        var cuFtNet = 0;\n\n        if (type === 'slab' || type === 'curb') {\n          var len = parseFloat(document.getElementById('slabLength').value) || 0;\n          var wid = parseFloat(document.getElementById('slabWidth').value) || 0;\n          var thickIn = parseFloat(document.getElementById('slabThickness').value) || 4;\n          cuFtNet = len * wid * (thickIn / 12);\n        } else {\n          var diamIn = parseFloat(document.getElementById('colDiameter').value) || 12;\n          var depthIn = parseFloat(document.getElementById('colDepth').value) || 36;\n          var count = parseInt(document.getElementById('colCount').value) || 1;\n          var radiusFt = (diamIn / 2) / 12;\n          var depthFt = depthIn / 12;\n          var singleVol = Math.PI * radiusFt * radiusFt * depthFt;\n          cuFtNet = singleVol * count;\n        }\n\n        var cuFtGross = cuFtNet * (1 + waste);\n        var cuYardsGross = cuFtGross / 27;\n        var cuMetersGross = cuFtGross * 0.0283168;\n\n        // Bag counts\n        var bags80 = Math.ceil(cuFtGross / 0.60);\n        var bags60 = Math.ceil(cuFtGross / 0.45);\n        var bags50 = Math.ceil(cuFtGross / 0.375);\n        var bags40 = Math.ceil(cuFtGross / 0.30);\n\n        var totalBagCost = bags80 * bagPrice;\n\n        // Update DOM\n        document.getElementById('concreteCuYds').textContent = cuYardsGross.toFixed(2);\n        document.getElementById('concreteCuFt').textContent = cuFtGross.toFixed(1) + ' cu ft | ' + cuMetersGross.toFixed(2) + ' m³';\n        document.getElementById('bags80Count').textContent = bags80.toLocaleString();\n        document.getElementById('estCostBags').textContent = 'Est. Bag Cost: $' + Math.round(totalBagCost).toLocaleString();\n\n        document.getElementById('bags60Count').textContent = bags60.toLocaleString();\n        document.getElementById('bags50Count').textContent = bags50.toLocaleString();\n        document.getElementById('bags40Count').textContent = bags40.toLocaleString();\n\n        // Advisory box\n        var advBox = document.getElementById('truckAdvisoryBox');\n        if (cuYardsGross >= 1.5) {\n          advBox.innerHTML =\n            '<div style=\"color:#3b82f6;font-weight:700;margin-bottom:0.25rem;display:flex;align-items:center;gap:0.4rem;\">' +\n              '<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M1 3h15v13H1zM16 8h4l3 3v5h-7V8z\"/><circle cx=\"5.5\" cy=\"18.5\" r=\"2.5\"/><circle cx=\"18.5\" cy=\"18.5\" r=\"2.5\"/></svg>' +\n              'Ready-Mix Concrete Truck Recommended' +\n            '</div>' +\n            '<p style=\"margin:0;color:var(--fg);\">' +\n              'At <strong>' + cuYardsGross.toFixed(2) + ' cubic yards</strong> (' + bags80 + ' eighty-pound bags), manual hand-mixing will take hours and risks cold joints. Ordering a ready-mix delivery truck ($140 - $190/yd³) is typically faster, higher quality, and less physically exhausting.' +\n            '</p>';\n        } else {\n          advBox.innerHTML =\n            '<div style=\"color:#10b981;font-weight:700;margin-bottom:0.25rem;display:flex;align-items:center;gap:0.4rem;\">' +\n              '<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>' +\n              'DIY Pre-Mix Bags Feasible' +\n            '</div>' +\n            '<p style=\"margin:0;color:var(--fg);\">' +\n              'At <strong>' + cuYardsGross.toFixed(2) + ' cubic yards</strong> (' + bags80 + ' bags), this project can be mixed on-site in a wheelbarrow or rented electric mixer. Fits in a standard pickup truck bed (payload ~' + (bags80 * 80).toLocaleString() + ' lbs).' +\n            '</p>';\n        }\n\n        renderCrossSection(type);\n      }\n\n      function renderCrossSection(type) {\n        var svg = document.getElementById('concreteCrossSectionSvg');\n        if (!svg) return;\n\n        var thick = document.getElementById('slabThickness').value;\n        var svgHtml = '';\n\n        // Subgrade\n        svgHtml += '<rect x=\"60\" y=\"130\" width=\"680\" height=\"50\" fill=\"#a8a29e\" opacity=\"0.4\" rx=\"2\"/>';\n        svgHtml += '<text x=\"70\" y=\"160\" fill=\"var(--fg)\" font-size=\"11\" font-weight=\"bold\">Compacted Crushed Stone Sub-Base (4\" Depth)</text>';\n\n        // Concrete Slab\n        svgHtml += '<rect x=\"60\" y=\"50\" width=\"680\" height=\"80\" fill=\"#64748b\" opacity=\"0.8\" rx=\"4\"/>';\n        svgHtml += '<text x=\"70\" y=\"85\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"bold\">Poured Concrete Slab (' + thick + '\" Thickness)</text>';\n\n        // Rebar grid lines\n        svgHtml += '<line x1=\"80\" y1=\"95\" x2=\"720\" y2=\"95\" stroke=\"#ef4444\" stroke-width=\"3\" stroke-dasharray=\"8,6\"/>';\n        svgHtml += '<text x=\"70\" y=\"115\" fill=\"#fecaca\" font-size=\"10\">#4 Rebar / Welded Wire Mesh (Supported on 2\" Chairs)</text>';\n\n        // Dimension arrows\n        svgHtml += '<line x1=\"755\" y1=\"50\" x2=\"755\" y2=\"130\" stroke=\"var(--fg)\" stroke-width=\"2\"/>';\n        svgHtml += '<line x1=\"750\" y1=\"50\" x2=\"760\" y2=\"50\" stroke=\"var(--fg)\" stroke-width=\"2\"/>';\n        svgHtml += '<line x1=\"750\" y1=\"130\" x2=\"760\" y2=\"130\" stroke=\"var(--fg)\" stroke-width=\"2\"/>';\n        svgHtml += '<text x=\"770\" y=\"95\" fill=\"var(--fg)\" font-size=\"12\" font-weight=\"bold\">' + thick + '\"</text>';\n\n        svg.innerHTML = svgHtml;\n      }\n\n      function copyOrderSheet() {\n        var yds = document.getElementById('concreteCuYds').textContent;\n        var cuft = document.getElementById('concreteCuFt').textContent;\n        var b80 = document.getElementById('bags80Count').textContent;\n        var b60 = document.getElementById('bags60Count').textContent;\n        var b50 = document.getElementById('bags50Count').textContent;\n        var cost = document.getElementById('estCostBags').textContent;\n        var type = document.getElementById('structureType').options[document.getElementById('structureType').selectedIndex].text;\n\n        var text = '📋 Concrete Materials Order Sheet\\n' +\n          '• Project Type: ' + type + '\\n' +\n          '• Total Volume: ' + yds + ' Cubic Yards (' + cuft + ')\\n' +\n          '• 80 lb Bags Needed: ' + b80 + ' bags\\n' +\n          '• 60 lb Bags Needed: ' + b60 + ' bags\\n' +\n          '• 50 lb Bags Needed: ' + b50 + ' bags\\n' +\n          '• ' + cost + '\\n' +\n          '• Sub-base: Recommended 4\" compacted #57 gravel\\n\\n' +\n          'Calculated at digitaltoolsshed.com/calc/concrete-calculator';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyConcreteBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '<span>✓ Copied Order Sheet!</span>';\n          setTimeout(function() { btn.innerHTML = orig; }, 2000);\n        });\n      }\n\n      document.getElementById('structureType').addEventListener('change', function() {\n        var isSlab = this.value === 'slab' || this.value === 'curb';\n        document.getElementById('slabInputs').style.display = isSlab ? 'block' : 'none';\n        document.getElementById('columnInputs').style.display = isSlab ? 'none' : 'block';\n        calcConcrete();\n      });\n\n      var inputs = ['slabLength', 'slabWidth', 'slabThickness', 'colDiameter', 'colDepth', 'colCount', 'wasteFactor', 'bagPrice80'];\n      inputs.forEach(function(id) {\n        var el = document.getElementById(id);\n        if (el) {\n          el.addEventListener('input', calcConcrete);\n          el.addEventListener('change', calcConcrete);\n        }\n      });\n\n      document.getElementById('copyConcreteBtn').addEventListener('click', copyOrderSheet);\n\n      calcConcrete();\n    })();\n  </script>\n</div>\n";

  writeFileSync(join(calcDir, 'concrete-calculator.html'), renderPage({
    title: "Concrete Calculator: Slabs, Footings, Sonotubes & Bags (80lb / 60lb) | Digital Tools Shed",
    metaDesc: "Calculate exact concrete cubic yards, cubic meters, and pre-mix bags (80lb, 60lb, 50lb) for slabs, footings, and round columns with waste buffers and ready-mix truck cost comparisons.",
    canonical: `${DOMAIN}/calc/concrete-calculator`,
    bodyContent: concreteBody,
    currentPath: '/calc/concrete-calculator',
    faq: [
  {
    "q": "How many 80 lb bags of concrete do I need for one cubic yard?",
    "a": "It takes exactly 45 bags of 80 lb pre-mix concrete to equal one cubic yard (27 cubic feet). For 60 lb bags, you need 60 bags; for 50 lb bags, 72 bags; and for 40 lb bags, 90 bags. Always purchase 10% extra to account for subgrade unevenness and spillage."
  },
  {
    "q": "When should I order a ready-mix truck instead of buying pre-mix bags?",
    "a": "As a rule of thumb, projects requiring more than 1.0 to 1.5 cubic yards (45 to 65 eighty-pound bags) should be ordered via a ready-mix concrete truck. Hand-mixing more than 50 bags is physically brutal, takes hours, and risks cold joints where early batches set before later batches are poured."
  },
  {
    "q": "How thick should a concrete slab be for a patio, driveway, or shed?",
    "a": "Standard pedestrian sidewalks and light garden patios should be 3.5 to 4 inches thick. Shed floors and residential driveways supporting passenger cars should be 4 to 5 inches thick. Driveways supporting heavy pickup trucks, RVs, or commercial equipment require 6 to 8 inches with rebar reinforcement."
  },
  {
    "q": "How do you calculate concrete yardage for a rectangular slab?",
    "a": "Multiply Length (ft) × Width (ft) × Thickness (ft) and divide by 27. For example, a 10 ft by 20 ft slab that is 4 inches thick: 10 × 20 × (4 / 12) = 66.67 cu ft. Divide by 27 = 2.47 cubic yards. Adding 10% waste equals 2.72 cubic yards."
  },
  {
    "q": "Why is a compacted gravel base necessary under a concrete slab?",
    "a": "A 4-inch compacted gravel base (such as 3/4\" crushed aggregate) provides uniform structural support, facilitates critical water drainage under the slab, and prevents frost heave cracking during freezing winter temperatures."
  }
]
  }));

  // ─────────────────────────────────────────────────────────────────────────────
  // 3. DRYWALL & SCREW ESTIMATOR
  // ─────────────────────────────────────────────────────────────────────────────
  const drywallBody = "\n<div class=\"article-container\" style=\"max-width:1040px;margin:0 auto;padding:1.5rem 1rem;\">\n  <div style=\"margin-bottom:2rem;border-bottom:1px solid var(--border);padding-bottom:1.5rem;\">\n    <div style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.85rem;color:var(--text-muted);margin-bottom:0.5rem;\">\n      <a href=\"/\" style=\"color:inherit;text-decoration:none;\">Home</a> &gt; <a href=\"/calc/\" style=\"color:inherit;text-decoration:none;\">Trade & Construction</a> &gt; <span>Drywall Calculator</span>\n    </div>\n    <h1 style=\"font-family:var(--serif);font-size:2.3rem;margin-bottom:0.75rem;line-height:1.2;\">Drywall Sheets, Mud, Screws & Tape Calculator</h1>\n    <p style=\"color:var(--text-muted);font-size:1.05rem;line-height:1.6;margin:0;\">\n      Calculate complete drywall material requirements for any room or basement remodel. Computes 4x8 and 4x12 sheetrock counts, 4.5-gallon all-purpose joint compound buckets, 1-1/4\" drywall screws, and tape rolls with door/window subtractions and hanging waste factors.\n    </p>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(320px, 1fr));gap:2rem;margin-bottom:2.5rem;\">\n    <!-- INPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n      <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:1.25rem;display:flex;align-items:center;gap:0.5rem;\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"/></svg>\n        Room Dimensions\n      </h2>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roomLength\">Length (Feet)</label>\n          <input type=\"number\" id=\"roomLength\" value=\"16\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roomWidth\">Width (Feet)</label>\n          <input type=\"number\" id=\"roomWidth\" value=\"12\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"ceilingHeight\">Ceiling Height</label>\n          <select id=\"ceilingHeight\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"8\" selected>8 Ft (Standard)</option>\n            <option value=\"9\">9 Ft (Modern Residential)</option>\n            <option value=\"10\">10 Ft (High Ceiling)</option>\n            <option value=\"12\">12 Ft (Vaulted / Commercial)</option>\n          </select>\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"sheetSize\">Sheet Size</label>\n          <select id=\"sheetSize\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"32\" selected>4x8 Ft (32 sq ft — Standard)</option>\n            <option value=\"48\">4x12 Ft (48 sq ft — Fewer Seams)</option>\n          </select>\n        </div>\n      </div>\n\n      <div style=\"margin-bottom:1.25rem;\">\n        <label style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.875rem;cursor:pointer;font-weight:600;\">\n          <input type=\"checkbox\" id=\"includeCeiling\" checked style=\"accent-color:var(--fg);\">\n          <span>Include Ceiling Drywall in Estimate</span>\n        </label>\n      </div>\n\n      <!-- OPENINGS DEDUCTIONS -->\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"doorCount\">Doors (Subtract 21 sq ft)</label>\n          <input type=\"number\" id=\"doorCount\" value=\"2\" min=\"0\" max=\"10\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"windowCount\">Windows (Subtract 15 sq ft)</label>\n          <input type=\"number\" id=\"windowCount\" value=\"2\" min=\"0\" max=\"15\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n      </div>\n\n      <div>\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wastePct\">Waste Allowance (%)</label>\n        <select id=\"wastePct\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n          <option value=\"10\" selected>10% (Recommended Standard)</option>\n          <option value=\"15\">15% (Complex Room / Many Cutouts)</option>\n          <option value=\"5\">5% (Simple Rectangular Box)</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- SUMMARY & OUTPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);display:flex;flex-direction:column;justify-content:space-between;\">\n      <div>\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;\">\n          <h2 style=\"font-size:1.25rem;margin:0;display:flex;align-items:center;gap:0.5rem;\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n            Drywall Material Takeoff\n          </h2>\n          <button id=\"copyDrywallBtn\" style=\"padding:0.4rem 0.75rem;font-size:0.8rem;background:var(--bg);border:1px solid var(--border);border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;gap:0.35rem;font-family:var(--sans);\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            <span>Copy Takeoff</span>\n          </button>\n        </div>\n\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.5rem;\">\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Total Drywall Sheets</span>\n            <span id=\"drywallSheetCount\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">22</span>\n            <span id=\"sheetSizeLabel\" style=\"font-size:0.8rem;color:#3b82f6;font-weight:600;\">4x8 Ft Panels</span>\n          </div>\n\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Net Surface Area</span>\n            <span id=\"netSquareFootage\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">640</span>\n            <span id=\"grossSquareFootage\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">704 sq ft with waste</span>\n          </div>\n        </div>\n\n        <!-- ACCESSORIES BREAKDOWN TABLE -->\n        <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;margin-bottom:1.5rem;\">\n          <div style=\"font-size:0.8rem;font-weight:600;color:var(--text-muted);margin-bottom:0.75rem;text-transform:uppercase;letter-spacing:0.05em;\">Finishing Fasteners & Supplies</div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Joint Compound (Mud):</span>\n            <strong id=\"mudBuckets\" style=\"font-family:var(--mono);color:#10b981;\">2 Buckets (4.5 Gal)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>1-1/4\" Drywall Screws:</span>\n            <strong id=\"screwsCount\" style=\"font-family:var(--mono);color:var(--fg);\">3 lbs (~750 screws)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Joint Tape (Paper/Fiber):</span>\n            <strong id=\"tapeRolls\" style=\"font-family:var(--mono);color:var(--fg);\">1 Roll (250 ft)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;font-size:0.875rem;\">\n            <span>Wall vs Ceiling Split:</span>\n            <span id=\"wallCeilingRatio\" style=\"font-family:var(--mono);color:var(--text-muted);\">448 sq ft wall / 192 sq ft ceiling</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- INTERACTIVE SVG ROOM UNFOLDED PLAN -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n    <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:0.5rem;\">Unfolded Room Drywall Surface Layout</h2>\n    <p style=\"color:var(--text-muted);font-size:0.9rem;margin-bottom:1.5rem;\">\n      Architectural unfolded elevation displaying all four perimeter walls and center ceiling with deducted door and window openings.\n    </p>\n\n    <div style=\"overflow-x:auto;\">\n      <svg id=\"drywallRoomSvg\" viewBox=\"0 0 800 280\" style=\"width:100%;height:auto;min-width:550px;font-family:var(--mono);\"></svg>\n    </div>\n  </div>\n\n  <!-- MATHEMATICAL & QUANTITY DERIVATIONS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1rem;font-family:var(--serif);\">Drywall Estimation Formulas & Industry Rule-of-Thumbs</h2>\n    <p style=\"color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1rem;\">\n      Professional drywall contractors compute gross envelope area and subtract standard opening constants ($21 \\text{ sq ft}$ for standard $3'0'' \\times 6'8''$ doors; $15 \\text{ sq ft}$ for standard $3'0'' \\times 5'0''$ windows) before applying waste multipliers.\n    </p>\n\n    <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;font-family:var(--mono);font-size:0.85rem;line-height:1.7;overflow-x:auto;\">\n      <strong>1. Total Gross Surface Area:</strong><br>\n      A_{\\text{walls}} = 2 \\times (L + W) \\times H, \\quad A_{\\text{ceiling}} = L \\times W<br><br>\n      <strong>2. Net Drywall Square Footage:</strong><br>\n      A_{\\text{net}} = (A_{\\text{walls}} + A_{\\text{ceiling}}) - (21 \\times N_{\\text{doors}} + 15 \\times N_{\\text{windows}})<br><br>\n      <strong>3. Panel Requirements:</strong><br>\n      N_{\\text{sheets}} = \\left\\lceil \\frac{A_{\\text{net}} \\times (1 + \\frac{\\text{Waste}_{\\%}}{100})}{\\text{Sheet Area (32 or 48)}} \\right\\rceil<br><br>\n      <strong>4. Joint Compound (Mud) Requirements:</strong><br>\n      \\text{Mud Volume} \\approx A_{\\text{net}} \\times 0.007 \\text{ gal/sq ft} \\quad (\\sim 1 \\text{ standard 4.5-gal bucket per } 650 \\text{ sq ft for 3 coats})<br><br>\n      <strong>5. Fasteners:</strong><br>\n      \\text{Screws} = N_{\\text{sheets}} \\times 32 \\text{ screws/sheet} \\quad (16'' \\text{ O.C. stud framing})\n    </div>\n  </div>\n\n  <!-- 5 CRITICAL DRYWALL TRAPS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1.25rem;font-family:var(--serif);\">5 Critical Drywall Hanging & Finishing Pitfalls</h2>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.25rem;\">\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">1. Aligning Seams Directly Over Door & Window Corners</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Placing a drywall joint directly in line with a door jamb or window header causes guaranteed diagonal stress cracks when the house naturally settles or the door slams. Always notch drywall panels in an \"L-shape\" around corners so seams are offset at least 8 inches from rough openings.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">2. Over-Driving Drywall Screws Through the Paper</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Drywall screws must countersink just slightly below the surface without puncturing the paper facing. The gypsum core has zero holding strength by itself; the tensile strength comes entirely from the paper face. Puncturing the paper renders the screw completely useless.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">3. Hanging Walls Before Ceilings</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Always hang ceiling drywall panels first. When you subsequently hang the wall panels tight against the ceiling, the top edges of the wall sheets mechanically support the perimeter edges of the ceiling panels, preventing ceiling perimeter sag and eliminating corner cracking.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">4. Hanging Drywall Vertically Instead of Horizontally</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Residential walls should always be hung horizontally. Running panels perpendicular to wall studs bridges framing inconsistencies, increases structural shear strength, and eliminates up to 25% of linear tape seams while placing joints at a comfortable working height (48 inches).\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">5. Premature Second-Coating Joint Compound</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Applying a second or third coat of joint compound before the base coat has thoroughly dried and shrunk results in alligator cracking and joint tape blisters. Standard drying takes 24 hours per coat; use setting-type \"hot mud\" (Durabond 45/90) if same-day multi-coating is required.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT ENGINE -->\n  <script>\n    (function() {\n      function calcDrywall() {\n        var len = parseFloat(document.getElementById('roomLength').value) || 0;\n        var wid = parseFloat(document.getElementById('roomWidth').value) || 0;\n        var h = parseFloat(document.getElementById('ceilingHeight').value) || 8;\n        var incCeil = document.getElementById('includeCeiling').checked;\n        var sheetSqFt = parseFloat(document.getElementById('sheetSize').value) || 32;\n        var doors = parseInt(document.getElementById('doorCount').value) || 0;\n        var windows = parseInt(document.getElementById('windowCount').value) || 0;\n        var waste = (parseFloat(document.getElementById('wastePct').value) || 10) / 100;\n\n        var wallSqFt = 2 * (len + wid) * h;\n        var ceilSqFt = incCeil ? (len * wid) : 0;\n        var totalGross = wallSqFt + ceilSqFt;\n\n        var deductions = (doors * 21) + (windows * 15);\n        var netSqFt = Math.max(0, totalGross - deductions);\n        var grossWithWaste = netSqFt * (1 + waste);\n\n        var numSheets = Math.ceil(grossWithWaste / sheetSqFt);\n\n        // Materials\n        var mudGal = netSqFt * 0.007;\n        var mudBuckets = Math.max(1, Math.ceil(mudGal / 4.5));\n        var totalScrews = numSheets * 32;\n        var screwsLbs = Math.max(1, Math.ceil(totalScrews / 280)); // ~280 1-1/4\" screws per lb\n        var tapeFt = netSqFt * 0.4;\n        var tapeRolls = Math.max(1, Math.ceil(tapeFt / 250));\n\n        // Update DOM\n        document.getElementById('drywallSheetCount').textContent = numSheets;\n        document.getElementById('sheetSizeLabel').textContent = sheetSqFt === 48 ? '4x12 Ft Panels' : '4x8 Ft Panels';\n        document.getElementById('netSquareFootage').textContent = Math.round(netSqFt).toLocaleString();\n        document.getElementById('grossSquareFootage').textContent = Math.round(grossWithWaste).toLocaleString() + ' sq ft with waste';\n\n        document.getElementById('mudBuckets').textContent = mudBuckets + ' Bucket' + (mudBuckets > 1 ? 's' : '') + ' (4.5 Gal)';\n        document.getElementById('screwsCount').textContent = screwsLbs + ' lbs (~' + totalScrews.toLocaleString() + ' screws)';\n        document.getElementById('tapeRolls').textContent = tapeRolls + ' Roll' + (tapeRolls > 1 ? 's' : '') + ' (250 ft)';\n        document.getElementById('wallCeilingRatio').textContent = Math.round(wallSqFt) + ' sq ft wall' + (incCeil ? ' / ' + Math.round(ceilSqFt) + ' sq ft ceiling' : ' (No ceiling)');\n\n        renderRoomSvg(len, wid, h, incCeil);\n      }\n\n      function renderRoomSvg(len, wid, h, incCeil) {\n        var svg = document.getElementById('drywallRoomSvg');\n        if (!svg) return;\n\n        var svgHtml = '';\n        var startX = 60;\n        var startY = 30;\n\n        // Visual representation of 4 walls\n        var wallW = 150;\n        var wallH = 100;\n        var gap = 15;\n\n        var labels = ['North Wall (' + len + \"')\", 'East Wall (' + wid + \"')\", 'South Wall (' + len + \"')\", 'West Wall (' + wid + \"')\"];\n\n        for (var i = 0; i < 4; i++) {\n          var x = startX + i * (wallW + gap);\n          svgHtml += '<rect x=\"' + x + '\" y=\"' + startY + '\" width=\"' + wallW + '\" height=\"' + wallH + '\" fill=\"var(--surface)\" stroke=\"var(--border)\" stroke-width=\"2\" rx=\"4\"/>';\n          svgHtml += '<text x=\"' + (x + wallW/2) + '\" y=\"' + (startY + 25) + '\" fill=\"var(--fg)\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">' + labels[i] + '</text>';\n          svgHtml += '<text x=\"' + (x + wallW/2) + '\" y=\"' + (startY + 50) + '\" fill=\"var(--text-muted)\" font-size=\"10\" text-anchor=\"middle\">' + h + \"' Height</text>\";\n\n          // Seam line\n          svgHtml += '<line x1=\"' + x + '\" y1=\"' + (startY + wallH/2) + '\" x2=\"' + (x + wallW) + '\" y2=\"' + (startY + wallH/2) + '\" stroke=\"#3b82f6\" stroke-dasharray=\"4,3\" stroke-width=\"1.5\"/>';\n        }\n\n        // Ceiling box if included\n        if (incCeil) {\n          var ceilY = startY + wallH + 20;\n          svgHtml += '<rect x=\"' + startX + '\" y=\"' + ceilY + '\" width=\"' + (4 * wallW + 3 * gap) + '\" height=\"90\" fill=\"var(--bg)\" stroke=\"#10b981\" stroke-width=\"2\" rx=\"4\"/>';\n          svgHtml += '<text x=\"' + (startX + 20) + '\" y=\"' + (ceilY + 30) + '\" fill=\"#10b981\" font-size=\"13\" font-weight=\"bold\">Ceiling Surface (' + len + \"' x \" + wid + \"')</text>\";\n          svgHtml += '<text x=\"' + (startX + 20) + '\" y=\"' + (ceilY + 55) + '\" fill=\"var(--text-muted)\" font-size=\"11\">Hang ceiling panels first before walls to support perimeter edges.</text>';\n        }\n\n        svg.innerHTML = svgHtml;\n      }\n\n      function copyTakeoff() {\n        var sheets = document.getElementById('drywallSheetCount').textContent;\n        var sheetType = document.getElementById('sheetSizeLabel').textContent;\n        var net = document.getElementById('netSquareFootage').textContent;\n        var gross = document.getElementById('grossSquareFootage').textContent;\n        var mud = document.getElementById('mudBuckets').textContent;\n        var screws = document.getElementById('screwsCount').textContent;\n        var tape = document.getElementById('tapeRolls').textContent;\n\n        var text = '📋 Drywall Material Takeoff & Order Sheet\\n' +\n          '• Drywall Sheets: ' + sheets + ' (' + sheetType + ')\\n' +\n          '• Net Surface Area: ' + net + ' sq ft (' + gross + ')\\n' +\n          '• Joint Compound: ' + mud + '\\n' +\n          '• Drywall Screws: ' + screws + '\\n' +\n          '• Joint Tape: ' + tape + '\\n\\n' +\n          'Calculated at digitaltoolsshed.com/calc/drywall-calculator';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyDrywallBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '<span>✓ Copied Takeoff!</span>';\n          setTimeout(function() { btn.innerHTML = orig; }, 2000);\n        });\n      }\n\n      var inputs = ['roomLength', 'roomWidth', 'ceilingHeight', 'includeCeiling', 'sheetSize', 'doorCount', 'windowCount', 'wastePct'];\n      inputs.forEach(function(id) {\n        var el = document.getElementById(id);\n        if (el) {\n          el.addEventListener('input', calcDrywall);\n          el.addEventListener('change', calcDrywall);\n        }\n      });\n\n      document.getElementById('copyDrywallBtn').addEventListener('click', copyTakeoff);\n\n      calcDrywall();\n    })();\n  </script>\n</div>\n";

  writeFileSync(join(calcDir, 'drywall-calculator.html'), renderPage({
    title: "Drywall Calculator: Sheets (4x8 & 4x12), Mud, Screws & Tape Estimator | Digital Tools Shed",
    metaDesc: "Calculate exact drywall sheets (4x8 and 4x12), joint compound buckets, screws, and tape rolls for any room with automatic window and door deductions.",
    canonical: `${DOMAIN}/calc/drywall-calculator`,
    bodyContent: drywallBody,
    currentPath: '/calc/drywall-calculator',
    faq: [
  {
    "q": "How many 4x8 drywall sheets do I need for a 12x12 room?",
    "a": "A standard 12x12 foot room with 8-foot ceilings requires approximately 18 sheets of 4x8 drywall (12 sheets for the perimeter walls and 5 to 6 sheets for the ceiling, accounting for door and window subtractions and standard 10% cutting waste)."
  },
  {
    "q": "Should I hang drywall horizontally or vertically on residential walls?",
    "a": "Hang drywall horizontally (perpendicular to wall studs). Horizontal installation increases wall shear strength, bridges minor stud bowing, reduces the total linear footage of tape joints by roughly 25%, and places seams at a convenient 48-inch working height."
  },
  {
    "q": "Why must ceiling drywall always be hung before wall drywall?",
    "a": "Ceiling panels must be installed first so the top edges of the wall panels press tight underneath them, physically supporting the perimeter of the ceiling sheets. This eliminates ceiling perimeter sag and prevents corner seam cracking."
  },
  {
    "q": "How much joint compound (mud) do I need per drywall sheet?",
    "a": "As a reliable rule of thumb, plan for approximately 0.053 gallons of joint compound per 4x8 sheet across three coats (taping coat, filler coat, and finish skim coat). A 4.5-gallon bucket typically covers about 75 to 85 sheets of drywall or roughly 600 to 700 square feet."
  },
  {
    "q": "What is the advantage of using 4x12 drywall sheets instead of 4x8 sheets?",
    "a": "4x12 foot panels cover 48 square feet per sheet compared to 32 square feet for a 4x8 panel. On long walls, 12-foot sheets eliminate vertical butt joints entirely, creating smoother walls that are much faster to tape and finish with fewer visible seams."
  }
]
  }));

