  const mulchBody = "\n<div class=\"article-container\" style=\"max-width:1040px;margin:0 auto;padding:1.5rem 1rem;\">\n  <div style=\"margin-bottom:2rem;border-bottom:1px solid var(--border);padding-bottom:1.5rem;\">\n    <div style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.85rem;color:var(--text-muted);margin-bottom:0.5rem;\">\n      <a href=\"/\" style=\"color:inherit;text-decoration:none;\">Home</a> &gt; <a href=\"/calc/\" style=\"color:inherit;text-decoration:none;\">Trade & Construction</a> &gt; <span>Mulch Calculator</span>\n    </div>\n    <h1 style=\"font-family:var(--serif);font-size:2.3rem;margin-bottom:0.75rem;line-height:1.2;\">Mulch, Topsoil & Compost Yardage Calculator</h1>\n    <p style=\"color:var(--text-muted);font-size:1.05rem;line-height:1.6;margin:0;\">\n      Calculate cubic yards and exact bag counts (2.0 and 3.0 cu ft) for flower beds, garden soil, and circular tree rings. Features automatic depth optimization (2\" to 4\"), settling allowance, and bulk landscape yard truckload vs bagged price comparisons.\n    </p>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(320px, 1fr));gap:2rem;margin-bottom:2.5rem;\">\n    <!-- INPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n      <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:1.25rem;display:flex;align-items:center;gap:0.5rem;\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 0 0-7.07 17.07A10 10 0 0 0 12 22a10 10 0 0 0 7.07-2.93A10 10 0 0 0 12 2z\"/></svg>\n        Garden Bed Dimensions\n      </h2>\n\n      <div style=\"margin-bottom:1.25rem;\">\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"bedShape\">Bed Geometry</label>\n        <select id=\"bedShape\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n          <option value=\"rect\" selected>Rectangular Garden Bed (Length x Width)</option>\n          <option value=\"circle\">Circular Tree Ring (Radius)</option>\n          <option value=\"sqft\">Direct Total Square Footage</option>\n        </select>\n      </div>\n\n      <!-- RECTANGULAR BED INPUTS -->\n      <div id=\"rectBedInputs\">\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"bedLength\">Length (Feet)</label>\n            <input type=\"number\" id=\"bedLength\" value=\"30\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"bedWidth\">Width (Feet)</label>\n            <input type=\"number\" id=\"bedWidth\" value=\"6\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n        </div>\n      </div>\n\n      <!-- CIRCLE TREE RING INPUTS -->\n      <div id=\"circleBedInputs\" style=\"display:none;\">\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"ringRadius\">Radius (Feet)</label>\n            <input type=\"number\" id=\"ringRadius\" value=\"4\" min=\"1\" step=\"0.5\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n          <div>\n            <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"treeCount\">Number of Trees</label>\n            <input type=\"number\" id=\"treeCount\" value=\"3\" min=\"1\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n          </div>\n        </div>\n      </div>\n\n      <!-- DIRECT SQFT INPUT -->\n      <div id=\"directSqFtInputs\" style=\"display:none;margin-bottom:1.25rem;\">\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"customSqFt\">Total Bed Area (Sq Ft)</label>\n        <input type=\"number\" id=\"customSqFt\" value=\"180\" min=\"1\" step=\"10\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"mulchDepth\">Mulch Layer Depth</label>\n          <select id=\"mulchDepth\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"2\">2\" (Annual Top-Dress / Refresh)</option>\n            <option value=\"3\" selected>3\" (Recommended Standard)</option>\n            <option value=\"4\">4\" (New Bed Weed Barrier)</option>\n          </select>\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"bagCost\">Price / 2 cu ft Bag ($)</label>\n          <input type=\"number\" id=\"bagCost\" value=\"3.98\" min=\"0\" step=\"0.25\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n      </div>\n    </div>\n\n    <!-- SUMMARY & OUTPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);display:flex;flex-direction:column;justify-content:space-between;\">\n      <div>\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;\">\n          <h2 style=\"font-size:1.25rem;margin-top:0;display:flex;align-items:center;gap:0.5rem;\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n            Mulch Order Estimate\n          </h2>\n          <button id=\"copyMulchBtn\" style=\"padding:0.4rem 0.75rem;font-size:0.8rem;background:var(--bg);border:1px solid var(--border);border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;gap:0.35rem;font-family:var(--sans);\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            <span>Copy Order List</span>\n          </button>\n        </div>\n\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.5rem;\">\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Cubic Yards Needed</span>\n            <span id=\"mulchCuYds\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">1.67</span>\n            <span id=\"mulchCuFt\" style=\"font-size:0.8rem;color:#3b82f6;font-weight:600;\">45.0 cu ft | 1.27 m³</span>\n          </div>\n\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Standard 2 Cu Ft Bags</span>\n            <span id=\"mulch2CuFtBags\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">23</span>\n            <span id=\"mulchEstCost\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">Est. Cost: $91</span>\n          </div>\n        </div>\n\n        <!-- ALTERNATIVE BAGS & ADVISORY -->\n        <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;margin-bottom:1.5rem;\">\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>3.0 Cu Ft Bag Equivalent:</span>\n            <strong id=\"mulch3CuFtBags\" style=\"font-family:var(--mono);color:var(--fg);\">15 Bags</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;font-size:0.875rem;\">\n            <span>Delivery Recommendation:</span>\n            <strong id=\"bulkVsBagAdvisory\" style=\"font-family:var(--mono);color:#10b981;\">Store Bags Feasible</strong>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- INTERACTIVE SVG SOIL STRATA CROSS-SECTION -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n    <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:0.5rem;\">Landscape Bed Cross-Section & Root Zone</h2>\n    <p style=\"color:var(--text-muted);font-size:0.9rem;margin-bottom:1.5rem;\">\n      Optimal mulch thickness prevents soil weed germination while permitting rain infiltration and oxygen transfer to root crowns.\n    </p>\n\n    <div style=\"overflow-x:auto;\">\n      <svg id=\"mulchCrossSectionSvg\" viewBox=\"0 0 800 180\" style=\"width:100%;height:auto;min-width:550px;font-family:var(--mono);\"></svg>\n    </div>\n  </div>\n\n  <!-- MATHEMATICAL & VOLUME DERIVATIONS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1rem;font-family:var(--serif);\">Mulch Volume Formulas & Standard Bulk Ratios</h2>\n    <p style=\"color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1rem;\">\n      Bulk landscaping materials are universally measured in cubic yards ($1 \\text{ yd}^3 = 27 \\text{ ft}^3$). One cubic yard spread at a depth of 3 inches covers exactly 108 square feet ($27 \\div 0.25 = 108$).\n    </p>\n\n    <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;font-family:var(--mono);font-size:0.85rem;line-height:1.7;overflow-x:auto;\">\n      <strong>1. Volume in Cubic Feet:</strong><br>\n      V_{\\text{cu ft}} = \\text{Area (sq ft)} \\times \\frac{\\text{Depth (inches)}}{12}<br><br>\n      <strong>2. Volume in Cubic Yards:</strong><br>\n      V_{\\text{cu yds}} = \\frac{V_{\\text{cu ft}}}{27} = \\frac{\\text{Area} \\times \\text{Depth}}{324}<br><br>\n      <strong>3. Bag Conversion Constants:</strong><br>\n      \\text{Bags}_{2.0\\text{ cu ft}} = \\left\\lceil \\frac{V_{\\text{cu ft}}}{2.0} \\right\\rceil = \\lceil V_{\\text{cu yds}} \\times 13.5 \\rceil<br>\n      \\text{Bags}_{3.0\\text{ cu ft}} = \\left\\lceil \\frac{V_{\\text{cu ft}}}{3.0} \\right\\rceil = \\lceil V_{\\text{cu yds}} \\times 9.0 \\rceil\n    </div>\n  </div>\n\n  <!-- 5 CRITICAL MULCHING TRAPS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1.25rem;font-family:var(--serif);\">5 Critical Mulching & Landscaping Pitfalls</h2>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.25rem;\">\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">1. The Destructive \"Mulch Volcano\"</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Piling mulch directly against tree trunks in a steep cone is the #1 cause of suburban tree mortality. Trunk bark requires air exchange; trapped moisture rots the phloem layer, suffocates root flares, and encourages rodents to chew through bark cambium. Keep mulch 3 to 6 inches away from trunks.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">2. Over-Mulching Suffocation (> 4 Inches)</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Applying more than 3 to 4 inches of mulch prevents oxygen and rainfall from reaching plant roots. In wet climates, thick mulch stays waterlogged, suffocating shallow feeder roots; in dry climates, thick mulch absorbs light rain like a sponge, preventing any moisture from penetrating into the soil below.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">3. Sour / Anaerobic Mulch Acidity Shock</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          When bulk mulch is piled high without airflow, anaerobic decomposition produces acetic acid, alcohol, and methane gas. This \"sour\" mulch smells like vinegar or rotten silage and has a toxic pH as low as 3.0. Applying sour mulch directly kills perennials and bleaches shrubs within 24 hours.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">4. Fresh Uncomposted Wood Chips Nitrogen Draw</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Fresh tree-trimming wood chips have an extreme carbon-to-nitrogen ratio (500:1). Soil bacteria consume all available nitrogen from the topsoil to break down the raw wood, causing neighboring annuals and vegetables to turn yellow and starve from severe nitrogen deficiency.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">5. Weed Barrier Fabric Layering Failure</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Installing plastic or woven landscape fabric under organic mulch creates a maintenance nightmare within 2 years. The organic mulch decomposes into fertile compost on top of the fabric. Windblown weed seeds germinate above the barrier and anchor their roots directly through the weave.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT ENGINE -->\n  <script>\n    (function() {\n      function calcMulch() {\n        var shape = document.getElementById('bedShape').value;\n        var depthIn = parseFloat(document.getElementById('mulchDepth').value) || 3;\n        var bagCost = parseFloat(document.getElementById('bagCost').value) || 3.98;\n\n        var areaSqFt = 0;\n        if (shape === 'rect') {\n          var len = parseFloat(document.getElementById('bedLength').value) || 0;\n          var wid = parseFloat(document.getElementById('bedWidth').value) || 0;\n          areaSqFt = len * wid;\n        } else if (shape === 'circle') {\n          var r = parseFloat(document.getElementById('ringRadius').value) || 0;\n          var count = parseInt(document.getElementById('treeCount').value) || 1;\n          areaSqFt = Math.PI * r * r * count;\n        } else {\n          areaSqFt = parseFloat(document.getElementById('customSqFt').value) || 0;\n        }\n\n        var cuFt = areaSqFt * (depthIn / 12);\n        var cuYds = cuFt / 27;\n        var cuMeters = cuFt * 0.0283168;\n\n        var bags2 = Math.ceil(cuFt / 2.0);\n        var bags3 = Math.ceil(cuFt / 3.0);\n        var totalCost = bags2 * bagCost;\n\n        // Update DOM\n        document.getElementById('mulchCuYds').textContent = cuYds.toFixed(2);\n        document.getElementById('mulchCuFt').textContent = cuFt.toFixed(1) + ' cu ft | ' + cuMeters.toFixed(2) + ' m³';\n        document.getElementById('mulch2CuFtBags').textContent = bags2.toLocaleString();\n        document.getElementById('mulch3CuFtBags').textContent = bags3.toLocaleString() + ' Bags (3.0 cu ft)';\n        document.getElementById('mulchEstCost').textContent = 'Est. Bag Cost: $' + Math.round(totalCost).toLocaleString();\n\n        var adv = document.getElementById('bulkVsBagAdvisory');\n        if (cuYds >= 3.0) {\n          adv.textContent = 'Bulk Delivery Recommended (3+ yd³)';\n          adv.style.color = '#3b82f6';\n        } else {\n          adv.textContent = 'Store Bags Feasible (< 3 yd³)';\n          adv.style.color = '#10b981';\n        }\n\n        renderStrata(depthIn);\n      }\n\n      function renderStrata(d) {\n        var svg = document.getElementById('mulchCrossSectionSvg');\n        if (!svg) return;\n\n        var svgHtml = '';\n        var startX = 60;\n        var startY = 30;\n        var w = 680;\n\n        var mulchH = d * 18; // scaled px\n        var soilH = 80;\n\n        // Mulch Layer\n        svgHtml += '<rect x=\"' + startX + '\" y=\"' + startY + '\" width=\"' + w + '\" height=\"' + mulchH + '\" fill=\"#78350f\" opacity=\"0.85\" rx=\"3\"/>';\n        svgHtml += '<text x=\"' + (startX + 20) + '\" y=\"' + (startY + mulchH/2 + 5) + '\" fill=\"#ffffff\" font-size=\"12\" font-weight=\"bold\">Organic Mulch Layer (' + d + '\" Depth)</text>';\n\n        // Native Soil\n        svgHtml += '<rect x=\"' + startX + '\" y=\"' + (startY + mulchH) + '\" width=\"' + w + '\" height=\"' + soilH + '\" fill=\"#451a03\" opacity=\"0.4\" rx=\"2\"/>';\n        svgHtml += '<text x=\"' + (startX + 20) + '\" y=\"' + (startY + mulchH + 35) + '\" fill=\"var(--fg)\" font-size=\"12\" font-weight=\"bold\">Native Topsoil & Active Root Zone</text>';\n\n        svg.innerHTML = svgHtml;\n      }\n\n      function copyOrder() {\n        var yds = document.getElementById('mulchCuYds').textContent;\n        var cuft = document.getElementById('mulchCuFt').textContent;\n        var b2 = document.getElementById('mulch2CuFtBags').textContent;\n        var b3 = document.getElementById('mulch3CuFtBags').textContent;\n        var cost = document.getElementById('mulchEstCost').textContent;\n\n        var text = '📋 Landscaping Mulch Order Takeoff\\n' +\n          '• Total Volume: ' + yds + ' Cubic Yards (' + cuft + ')\\n' +\n          '• 2.0 Cu Ft Bags: ' + b2 + ' bags\\n' +\n          '• 3.0 Cu Ft Bags: ' + b3 + '\\n' +\n          '• ' + cost + '\\n' +\n          '• Keep mulch 3-6 inches away from tree root flares\\n\\n' +\n          'Calculated at digitaltoolsshed.com/calc/mulch-calculator';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyMulchBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '<span>✓ Copied Order Sheet!</span>';\n          setTimeout(function() { btn.innerHTML = orig; }, 2000);\n        });\n      }\n\n      document.getElementById('bedShape').addEventListener('change', function() {\n        var s = this.value;\n        document.getElementById('rectBedInputs').style.display = s === 'rect' ? 'block' : 'none';\n        document.getElementById('circleBedInputs').style.display = s === 'circle' ? 'block' : 'none';\n        document.getElementById('directSqFtInputs').style.display = s === 'sqft' ? 'block' : 'none';\n        calcMulch();\n      });\n\n      var inputs = ['bedLength', 'bedWidth', 'ringRadius', 'treeCount', 'customSqFt', 'mulchDepth', 'bagCost'];\n      inputs.forEach(function(id) {\n        var el = document.getElementById(id);\n        if (el) {\n          el.addEventListener('input', calcMulch);\n          el.addEventListener('change', calcMulch);\n        }\n      });\n\n      document.getElementById('copyMulchBtn').addEventListener('click', copyOrder);\n\n      calcMulch();\n    })();\n  </script>\n</div>\n";

  writeFileSync(join(calcDir, 'mulch-calculator.html'), renderPage({
    title: "Mulch & Topsoil Calculator: Cubic Yards, Bags (2 & 3 Cu Ft) & Bed Depth | Digital Tools Shed",
    metaDesc: "Calculate exact mulch, topsoil, and compost cubic yards and bag counts (2 cu ft and 3 cu ft) for landscape beds and tree rings with bulk delivery cost comparisons.",
    canonical: `${DOMAIN}/calc/mulch-calculator`,
    bodyContent: mulchBody,
    currentPath: '/calc/mulch-calculator',
    faq: [
  {
    "q": "How many bags of mulch equal one cubic yard?",
    "a": "It takes exactly 13.5 bags of 2.0 cubic foot mulch to equal one cubic yard (27 cubic feet). For larger 3.0 cubic foot bags, you need 9 bags per cubic yard."
  },
  {
    "q": "How deep should mulch be in landscape and flower beds?",
    "a": "The ideal depth is 3 inches for standard landscape flower beds. A 3-inch layer is thick enough to block sunlight from reaching weed seeds and retain soil moisture, while still allowing water and air to reach plant roots. Never exceed 4 inches."
  },
  {
    "q": "How much square footage does one cubic yard of mulch cover?",
    "a": "At a 3-inch depth, one cubic yard of mulch covers exactly 108 square feet. At a 2-inch depth (annual top-dress), one cubic yard covers 162 square feet. At a 4-inch depth, it covers 81 square feet."
  },
  {
    "q": "When should I order bulk mulch delivery instead of bags?",
    "a": "If your project requires more than 3 cubic yards (40+ bags), ordering bulk delivery from a local landscape supply yard is significantly cheaper ($35 to $50 per cubic yard vs $60+ in bags) and eliminates hauling dozens of dirty plastic bags in your personal vehicle."
  },
  {
    "q": "What is a mulch volcano and why is it dangerous for trees?",
    "a": "A mulch volcano occurs when mulch is piled high against a tree trunk in a steep cone. Piling mulch against bark traps constant moisture, encouraging fungal rot, girdling roots, and insect infestation that suffocates and kills the tree. Mulch should always be kept 3 to 6 inches away from the root flare."
  }
]
  }));

  // ─────────────────────────────────────────────────────────────────────────────
  // 5. WALL FRAMING STUD CALCULATOR
  // ─────────────────────────────────────────────────────────────────────────────
  const studBody = "\n<div class=\"article-container\" style=\"max-width:1040px;margin:0 auto;padding:1.5rem 1rem;\">\n  <div style=\"margin-bottom:2rem;border-bottom:1px solid var(--border);padding-bottom:1.5rem;\">\n    <div style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.85rem;color:var(--text-muted);margin-bottom:0.5rem;\">\n      <a href=\"/\" style=\"color:inherit;text-decoration:none;\">Home</a> &gt; <a href=\"/calc/\" style=\"color:inherit;text-decoration:none;\">Trade & Construction</a> &gt; <span>Framing Stud Calculator</span>\n    </div>\n    <h1 style=\"font-family:var(--serif);font-size:2.3rem;margin-bottom:0.75rem;line-height:1.2;\">Wall Stud & Framing Lumber Takeoff Calculator</h1>\n    <p style=\"color:var(--text-muted);font-size:1.05rem;line-height:1.6;margin:0;\">\n      Calculate complete framing lumber lists for interior partition and load-bearing exterior walls. Accurately accounts for 16\" vs 24\" on-center spacing, bottom sole plates, double top plates, California 3-stud corners, T-junction drywall backers, and door/window king, jack, and cripple assemblies.\n    </p>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(320px, 1fr));gap:2rem;margin-bottom:2.5rem;\">\n    <!-- INPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n      <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:1.25rem;display:flex;align-items:center;gap:0.5rem;\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"22\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M4 4h16v16H4z\"/></svg>\n        Wall Framing Specifications\n      </h2>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wallLength\">Total Wall Length (Feet)</label>\n          <input type=\"number\" id=\"wallLength\" value=\"40\" min=\"1\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wallHeight\">Wall Height</label>\n          <select id=\"wallHeight\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"8\" selected>8 Ft (Standard 92-5/8\" Pre-Cut Studs)</option>\n            <option value=\"9\">9 Ft (104-5/8\" Pre-Cut Studs)</option>\n            <option value=\"10\">10 Ft (116-5/8\" Pre-Cut Studs)</option>\n          </select>\n        </div>\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"studSpacing\">Stud Spacing (O.C.)</label>\n          <select id=\"studSpacing\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"16\" selected>16\" On-Center (Standard Load-Bearing)</option>\n            <option value=\"24\">24\" On-Center (Advanced / Non-Bearing)</option>\n          </select>\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wallType\">Wall Structure Type</label>\n          <select id=\"wallType\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"exterior\" selected>Exterior / Bearing (Double Top Plate)</option>\n            <option value=\"interior\">Interior Partition (Single Top Plate)</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- CORNERS & INTERSECTIONS -->\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"cornerCount\">Corners (3-Stud Cal.)</label>\n          <input type=\"number\" id=\"cornerCount\" value=\"2\" min=\"0\" max=\"20\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"tJunctionCount\">T-Junction Intersections</label>\n          <input type=\"number\" id=\"tJunctionCount\" value=\"1\" min=\"0\" max=\"20\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n      </div>\n\n      <!-- ROUGH OPENINGS -->\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"doorOpenings\">Door Openings (+4 studs ea)</label>\n          <input type=\"number\" id=\"doorOpenings\" value=\"1\" min=\"0\" max=\"10\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"windowOpenings\">Window Openings (+5 studs ea)</label>\n          <input type=\"number\" id=\"windowOpenings\" value=\"2\" min=\"0\" max=\"15\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:0.95rem;\">\n        </div>\n      </div>\n\n      <div>\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"wasteAllowance\">Waste & Lumber Allowance (%)</label>\n        <select id=\"wasteAllowance\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n          <option value=\"15\" selected>15% (Recommended for Bows & Trimming)</option>\n          <option value=\"10\">10% (High Grade Select Lumber)</option>\n          <option value=\"20\">20% (Economy Utility Grade)</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- SUMMARY & LUMBER LIST COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);display:flex;flex-direction:column;justify-content:space-between;\">\n      <div>\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;\">\n          <h2 style=\"font-size:1.25rem;margin:0;display:flex;align-items:center;gap:0.5rem;\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n            Lumber Takeoff List\n          </h2>\n          <button id=\"copyFramingBtn\" style=\"padding:0.4rem 0.75rem;font-size:0.8rem;background:var(--bg);border:1px solid var(--border);border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;gap:0.35rem;font-family:var(--sans);\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            <span>Copy Takeoff</span>\n          </button>\n        </div>\n\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.5rem;\">\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Total Vertical Studs</span>\n            <span id=\"totalStudsCount\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">52</span>\n            <span id=\"studHeightLabel\" style=\"font-size:0.8rem;color:#3b82f6;font-weight:600;\">92-5/8\" Pre-Cuts (incl. waste)</span>\n          </div>\n\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Plate Lumber (16' Boards)</span>\n            <span id=\"plateBoardsCount\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">9</span>\n            <span id=\"plateLinearFt\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">120 Linear Feet Total</span>\n          </div>\n        </div>\n\n        <!-- BREAKDOWN LEDGER -->\n        <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;margin-bottom:1.5rem;\">\n          <div style=\"font-size:0.8rem;font-weight:600;color:var(--text-muted);margin-bottom:0.75rem;text-transform:uppercase;letter-spacing:0.05em;\">Lumber Component Itemization</div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Common Wall Studs (Field):</span>\n            <strong id=\"commonStudsVal\" style=\"font-family:var(--mono);\">31</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Corner & Intersection Backers:</span>\n            <strong id=\"cornersVal\" style=\"font-family:var(--mono);\">6 (Corners) + 2 (T-Junction)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Door & Window Assemblies (Kings/Jacks):</span>\n            <strong id=\"openingsStudsVal\" style=\"font-family:var(--mono);\">14 studs</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;font-size:0.875rem;\">\n            <span>Plate Structure:</span>\n            <span id=\"plateStructureDesc\" style=\"font-family:var(--mono);color:var(--fg);font-weight:600;\">3 Plates (Double Top + Sole Plate)</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- INTERACTIVE SVG FRAMING ELEVATION DIAGRAM -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n    <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:0.5rem;\">Wall Framing Elevation Schematic</h2>\n    <p style=\"color:var(--text-muted);font-size:0.9rem;margin-bottom:1.5rem;\">\n      Architectural framing layout displaying bottom sole plate, double top plates, 16\" on-center field studs, king studs, jack trimmers, and solid header assembly.\n    </p>\n\n    <div style=\"overflow-x:auto;\">\n      <svg id=\"framingWallSvg\" viewBox=\"0 0 800 240\" style=\"width:100%;height:auto;min-width:600px;font-family:var(--mono);\"></svg>\n    </div>\n  </div>\n\n  <!-- MATHEMATICAL & STRUCTURAL DERIVATIONS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1rem;font-family:var(--serif);\">Carpentry Formulas & On-Center Spacing Derivations</h2>\n    <p style=\"color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1rem;\">\n      Wall stud counts do not equal simple length division because framing requires an initial starting stud, plus framing assemblies for sheetrock backing at corners and load transfer around openings (IRC Chapter 6 Wall Construction).\n    </p>\n\n    <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;font-family:var(--mono);font-size:0.85rem;line-height:1.7;overflow-x:auto;\">\n      <strong>1. Common Field Studs:</strong><br>\n      N_{\\text{field}} = \\left\\lfloor \\frac{L_{\\text{ft}} \\times 12}{\\text{Spacing (16'' or 24'')} } \\right\\rfloor + 1<br><br>\n      <strong>2. Corner & Intersection Backers:</strong><br>\n      N_{\\text{corners}} = 3 \\times N_{\\text{exterior corners}} \\quad (\\text{California 3-stud corner}), \\quad N_{\\text{T-junctions}} = 2 \\times N_{\\text{intersections}}<br><br>\n      <strong>3. Opening King & Jack Assemblies:</strong><br>\n      N_{\\text{doors}} = 4 \\times N_{\\text{door openings}} \\quad (2 \\text{ Kings} + 2 \\text{ Jacks})<br>\n      N_{\\text{windows}} = 5 \\times N_{\\text{window openings}} \\quad (2 \\text{ Kings} + 2 \\text{ Jacks} + \\text{Cripple studs})<br><br>\n      <strong>4. Plate Linear Footage:</strong><br>\n      \\text{LF}_{\\text{plates}} = L_{\\text{ft}} \\times (\\text{Plates Count: } 3 \\text{ for double top, } 2 \\text{ for single top})<br><br>\n      <strong>5. Gross Stud Takeoff with Waste:</strong><br>\n      \\text{Total Studs} = \\left\\lceil (N_{\\text{field}} + N_{\\text{corners}} + N_{\\text{openings}}) \\times (1 + \\frac{\\text{Waste}_{\\%}}{100}) \\right\\rceil\n    </div>\n  </div>\n\n  <!-- 5 CRITICAL FRAMING TRAPS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1.25rem;font-family:var(--serif);\">5 Critical Wall Framing & IRC Code Pitfalls</h2>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.25rem;\">\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">1. Failing the 24\" Top Plate Stagger Rule</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          IRC Section R602.3.2 mandates that end joints in double top plates must be offset at least 24 inches (or 48 inches under high seismic/wind codes) from end joints in the plate below. Aligning top plate joints over lower plate joints creates a structural hinge that fails inspection.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">2. Missing Jack Stud Bearing Under Headers</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Toenailing a header directly to king studs without jack (trimmer) studs underneath is illegal for load-bearing walls. The entire roof or floor load above the header must bear directly on continuous vertical timber jack studs that extend down to the bottom plate.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">3. Omitting Horizontal Fireblocking</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          For walls over 10 feet tall, IRC Section R602.8 requires solid 2x4 horizontal blocking installed between studs at the midpoint. Omitting fireblocking creates open vertical chimneys inside walls that accelerate fire spread from floor to attic.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">4. Random Stud Crown Orientation</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Dimensional lumber studs always have a natural slight bend or arch along their narrow edge, known as the \"crown.\" If you frame adjacent studs with one crown facing inside and the next facing outside, your finished drywall will look severely wavy and buckled under glancing light. Always point all crowns the same direction.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">5. Using Drywall Screws for Structural Framing</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Never substitute drywall screws or interior gold screws for framing nails. Drywall screws are made of hardened, brittle steel with virtually zero shear strength. When a house shifts under wind or seismic loads, screw heads snap off instantly. Code requires 16d common nails (3.5\" × 0.162\") or approved structural fasteners.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT ENGINE -->\n  <script>\n    (function() {\n      function calcFraming() {\n        var len = parseFloat(document.getElementById('wallLength').value) || 0;\n        var h = parseFloat(document.getElementById('wallHeight').value) || 8;\n        var spacing = parseInt(document.getElementById('studSpacing').value) || 16;\n        var wallType = document.getElementById('wallType').value;\n        var corners = parseInt(document.getElementById('cornerCount').value) || 0;\n        var tJunctions = parseInt(document.getElementById('tJunctionCount').value) || 0;\n        var doors = parseInt(document.getElementById('doorOpenings').value) || 0;\n        var windows = parseInt(document.getElementById('windowOpenings').value) || 0;\n        var waste = (parseFloat(document.getElementById('wasteAllowance').value) || 15) / 100;\n\n        // Common field studs: (length_inches / spacing) + 1\n        var fieldStuds = Math.floor((len * 12) / spacing) + 1;\n\n        // Extra studs for corners (3-stud corner requires 2 extra studs beyond standard corner stud)\n        var cornerStuds = corners * 3;\n        var tJunctionStuds = tJunctions * 2;\n        var openingStuds = (doors * 4) + (windows * 5);\n\n        var baseStuds = fieldStuds + cornerStuds + tJunctionStuds + openingStuds;\n        var totalStuds = Math.ceil(baseStuds * (1 + waste));\n\n        // Plates: Exterior has 3 plates (1 sole + 2 top), interior partition has 2 plates (1 sole + 1 top)\n        var numPlates = wallType === 'exterior' ? 3 : 2;\n        var plateLF = len * numPlates;\n        // Standard 16-ft lumber boards\n        var plateBoards = Math.ceil((plateLF * (1 + 0.10)) / 16);\n\n        // Pre-cut stud label\n        var studLabel = h === 8 ? '92-5/8\" Pre-Cuts (incl. waste)' : (h === 9 ? '104-5/8\" Pre-Cuts' : '116-5/8\" Pre-Cuts');\n\n        // Update DOM\n        document.getElementById('totalStudsCount').textContent = totalStuds;\n        document.getElementById('studHeightLabel').textContent = studLabel;\n        document.getElementById('plateBoardsCount').textContent = plateBoards;\n        document.getElementById('plateLinearFt').textContent = plateLF + ' Linear Feet (' + numPlates + ' Plates)';\n\n        document.getElementById('commonStudsVal').textContent = fieldStuds;\n        document.getElementById('cornersVal').textContent = cornerStuds + ' (Corners) + ' + tJunctionStuds + ' (T-Junctions)';\n        document.getElementById('openingsStudsVal').textContent = openingStuds + ' studs (' + doors + ' doors, ' + windows + ' windows)';\n        document.getElementById('plateStructureDesc').textContent = numPlates + ' Plates (' + (wallType === 'exterior' ? 'Double Top + Bottom Sole' : 'Single Top + Bottom Sole') + ')';\n\n        renderFramingSvg(len, spacing, doors, windows);\n      }\n\n      function renderFramingSvg(len, spacing, doors, windows) {\n        var svg = document.getElementById('framingWallSvg');\n        if (!svg) return;\n\n        var svgHtml = '';\n        var startX = 50;\n        var startY = 30;\n        var wallW = 700;\n        var wallH = 160;\n\n        // Double Top Plate\n        svgHtml += '<rect x=\"' + startX + '\" y=\"' + startY + '\" width=\"' + wallW + '\" height=\"8\" fill=\"#eab308\" stroke=\"var(--border)\"/>';\n        svgHtml += '<rect x=\"' + startX + '\" y=\"' + (startY + 8) + '\" width=\"' + wallW + '\" height=\"8\" fill=\"#eab308\" stroke=\"var(--border)\"/>';\n\n        // Bottom Sole Plate\n        svgHtml += '<rect x=\"' + startX + '\" y=\"' + (startY + wallH - 8) + '\" width=\"' + wallW + '\" height=\"8\" fill=\"#eab308\" stroke=\"var(--border)\"/>';\n\n        // Vertical Studs\n        var numVisualStuds = Math.min(25, Math.floor(wallW / (spacing === 16 ? 30 : 45)));\n        var stepX = wallW / numVisualStuds;\n\n        for (var s = 0; s <= numVisualStuds; s++) {\n          var x = startX + s * stepX;\n          svgHtml += '<rect x=\"' + (x - 2) + '\" y=\"' + (startY + 16) + '\" width=\"5\" height=\"' + (wallH - 24) + '\" fill=\"#94a3b8\" stroke=\"none\"/>';\n        }\n\n        // Window opening in center if present\n        if (windows > 0) {\n          var winX = startX + wallW * 0.45;\n          var winW = 100;\n          var winY = startY + 45;\n          var winH = 70;\n          svgHtml += '<rect x=\"' + winX + '\" y=\"' + winY + '\" width=\"' + winW + '\" height=\"' + winH + '\" fill=\"var(--bg)\" stroke=\"#3b82f6\" stroke-width=\"2\"/>';\n          // Header above window\n          svgHtml += '<rect x=\"' + (winX - 5) + '\" y=\"' + (winY - 14) + '\" width=\"' + (winW + 10) + '\" height=\"14\" fill=\"#ef4444\"/>';\n          svgHtml += '<text x=\"' + (winX + winW/2) + '\" y=\"' + (winY + winH/2 + 4) + '\" fill=\"#3b82f6\" font-size=\"10\" font-weight=\"bold\" text-anchor=\"middle\">Window Opening</text>';\n        }\n\n        svg.innerHTML = svgHtml;\n      }\n\n      function copyFramingTakeoff() {\n        var studs = document.getElementById('totalStudsCount').textContent;\n        var studType = document.getElementById('studHeightLabel').textContent;\n        var plates = document.getElementById('plateBoardsCount').textContent;\n        var plateLF = document.getElementById('plateLinearFt').textContent;\n        var common = document.getElementById('commonStudsVal').textContent;\n        var corners = document.getElementById('cornersVal').textContent;\n        var openings = document.getElementById('openingsStudsVal').textContent;\n\n        var text = '📋 Wall Framing Lumber Takeoff & Cut List\\n' +\n          '• Total Wall Studs: ' + studs + ' (' + studType + ')\\n' +\n          '• 16-Ft Plate Boards: ' + plates + ' (' + plateLF + ')\\n' +\n          '• Common Field Studs: ' + common + '\\n' +\n          '• Corners & Drywall Backers: ' + corners + '\\n' +\n          '• Door & Window Studs: ' + openings + '\\n\\n' +\n          'Calculated at digitaltoolsshed.com/calc/framing-stud-calculator';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyFramingBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '<span>✓ Copied Takeoff!</span>';\n          setTimeout(function() { btn.innerHTML = orig; }, 2000);\n        });\n      }\n\n      var inputs = ['wallLength', 'wallHeight', 'studSpacing', 'wallType', 'cornerCount', 'tJunctionCount', 'doorOpenings', 'windowOpenings', 'wasteAllowance'];\n      inputs.forEach(function(id) {\n        var el = document.getElementById(id);\n        if (el) {\n          el.addEventListener('input', calcFraming);\n          el.addEventListener('change', calcFraming);\n        }\n      });\n\n      document.getElementById('copyFramingBtn').addEventListener('click', copyFramingTakeoff);\n\n      calcFraming();\n    })();\n  </script>\n</div>\n";

