  const roofingBody = "\n<div class=\"article-container\" style=\"max-width:1040px;margin:0 auto;padding:1.5rem 1rem;\">\n  <div style=\"margin-bottom:2rem;border-bottom:1px solid var(--border);padding-bottom:1.5rem;\">\n    <div style=\"display:flex;align-items:center;gap:0.5rem;font-size:0.85rem;color:var(--text-muted);margin-bottom:0.5rem;\">\n      <a href=\"/\" style=\"color:inherit;text-decoration:none;\">Home</a> &gt; <a href=\"/calc/\" style=\"color:inherit;text-decoration:none;\">Trade & Construction</a> &gt; <span>Roofing Calculator</span>\n    </div>\n    <h1 style=\"font-family:var(--serif);font-size:2.3rem;margin-bottom:0.75rem;line-height:1.2;\">Roofing Shingle, Squares & Pitch Calculator</h1>\n    <p style=\"color:var(--text-muted);font-size:1.05rem;line-height:1.6;margin:0;\">\n      Calculate exact architectural shingle bundles, roof squares (100 sq ft units), synthetic underlayment rolls, and roofing nails for any residential roof. Integrates pitch slope multipliers (3/12 to 12/12), eave overhang allowances, and hip/valley cutting waste.\n    </p>\n  </div>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(320px, 1fr));gap:2rem;margin-bottom:2.5rem;\">\n    <!-- INPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n      <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:1.25rem;display:flex;align-items:center;gap:0.5rem;\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/></svg>\n        Building Footprint & Pitch\n      </h2>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roofHouseLen\">Base Length (Feet)</label>\n          <input type=\"number\" id=\"roofHouseLen\" value=\"50\" min=\"10\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roofHouseWid\">Base Width (Feet)</label>\n          <input type=\"number\" id=\"roofHouseWid\" value=\"30\" min=\"10\" step=\"1\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:1rem;font-weight:600;\">\n        </div>\n      </div>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem;\">\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roofPitch\">Roof Pitch / Slope</label>\n          <select id=\"roofPitch\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"1.031\">3/12 (Low Slope — 14.0°)</option>\n            <option value=\"1.054\">4/12 (Moderate — 18.4°)</option>\n            <option value=\"1.083\">5/12 (Standard Ranch — 22.6°)</option>\n            <option value=\"1.118\" selected>6/12 (Standard Gable — 26.6°)</option>\n            <option value=\"1.158\">7/12 (Traditional — 30.3°)</option>\n            <option value=\"1.202\">8/12 (Steep Slope — 33.7°)</option>\n            <option value=\"1.250\">9/12 (Steep — 36.9°)</option>\n            <option value=\"1.302\">10/12 (Very Steep — 39.8°)</option>\n            <option value=\"1.414\">12/12 (Full 45° Pitch)</option>\n          </select>\n        </div>\n        <div>\n          <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"eaveOverhang\">Eave Overhang (Feet)</label>\n          <select id=\"eaveOverhang\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n            <option value=\"1.0\" selected>1.0 Ft (12\" Overhang Standard)</option>\n            <option value=\"1.5\">1.5 Ft (18\" Overhang)</option>\n            <option value=\"2.0\">2.0 Ft (24\" Wide Eaves)</option>\n            <option value=\"0\">0 Ft (Flush Gable / No Overhang)</option>\n          </select>\n        </div>\n      </div>\n\n      <div>\n        <label style=\"display:block;font-weight:600;font-size:0.875rem;margin-bottom:0.5rem;\" for=\"roofComplexity\">Roof Shape & Cutting Waste</label>\n        <select id=\"roofComplexity\" style=\"width:100%;padding:0.65rem 0.85rem;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);font-family:var(--sans);font-size:0.95rem;\">\n          <option value=\"10\" selected>Simple Gable Roof (10% Waste)</option>\n          <option value=\"15\">Hip Roof with Valleys (15% Waste)</option>\n          <option value=\"20\">Complex Multi-Dormer / Turrets (20% Waste)</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- SUMMARY & OUTPUT COLUMN -->\n    <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);display:flex;flex-direction:column;justify-content:space-between;\">\n      <div>\n        <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:1.25rem;\">\n          <h2 style=\"font-size:1.25rem;margin-top:0;display:flex;align-items:center;gap:0.5rem;\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\n            Roofing Material Takeoff\n          </h2>\n          <button id=\"copyRoofBtn\" style=\"padding:0.4rem 0.75rem;font-size:0.8rem;background:var(--bg);border:1px solid var(--border);border-radius:6px;cursor:pointer;display:inline-flex;align-items:center;gap:0.35rem;font-family:var(--sans);\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            <span>Copy Takeoff</span>\n          </button>\n        </div>\n\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.5rem;\">\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">Shingle Bundles (3/Sq)</span>\n            <span id=\"shingleBundlesCount\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">63 Bundles</span>\n            <span id=\"roofSquaresCount\" style=\"font-size:0.8rem;color:#3b82f6;font-weight:600;\">20.8 Roof Squares</span>\n          </div>\n\n          <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;\">\n            <span style=\"font-size:0.75rem;color:var(--text-muted);display:block;text-transform:uppercase;letter-spacing:0.05em;font-weight:600;margin-bottom:0.25rem;\">True Roof Surface Area</span>\n            <span id=\"trueRoofAreaSqFt\" style=\"font-family:var(--mono);font-size:2rem;font-weight:800;color:var(--fg);display:block;\">2,082</span>\n            <span id=\"groundFootprintLabel\" style=\"font-size:0.8rem;color:var(--text-muted);font-weight:600;\">1,664 sq ft ground area</span>\n          </div>\n        </div>\n\n        <!-- ACCESSORIES LEDGER -->\n        <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1rem;margin-bottom:1.5rem;\">\n          <div style=\"font-size:0.8rem;font-weight:600;color:var(--text-muted);margin-bottom:0.75rem;text-transform:uppercase;letter-spacing:0.05em;\">Underlayment & Fasteners</div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Synthetic Underlayment (10-Sq Rolls):</span>\n            <strong id=\"underlaymentRollsVal\" style=\"font-family:var(--mono);color:#10b981;\">3 Rolls</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Ice & Water Shield (36\" Eaves):</span>\n            <strong id=\"iceWaterShieldVal\" style=\"font-family:var(--mono);color:var(--fg);\">2 Rolls (132 linear ft)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;border-bottom:1px solid var(--border);font-size:0.875rem;\">\n            <span>Starter Strip Shingles:</span>\n            <strong id=\"starterStripsVal\" style=\"font-family:var(--mono);color:var(--fg);\">2 Bundles (~210 ft)</strong>\n          </div>\n          <div style=\"display:flex;justify-content:space-between;padding:0.35rem 0;font-size:0.875rem;\">\n            <span>1-1/4\" Coil Roofing Nails:</span>\n            <strong id=\"roofingNailsLbs\" style=\"font-family:var(--mono);color:var(--fg);\">55 lbs (~7,500 nails)</strong>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- INTERACTIVE SVG ROOF PITCH & PROFILE SCHEMATIC -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;box-shadow:0 4px 16px rgba(0,0,0,0.03);\">\n    <h2 style=\"font-size:1.25rem;margin-top:0;margin-bottom:0.5rem;\">Roof Pitch Geometry & Layer Cross-Section</h2>\n    <p style=\"color:var(--text-muted);font-size:0.9rem;margin-bottom:1.5rem;\">\n      Cross-sectional elevation illustrating roof pitch slope triangle, drip edge, ice & water barrier, synthetic felt, and architectural shingle exposure.\n    </p>\n\n    <div style=\"overflow-x:auto;\">\n      <svg id=\"roofSlopeSchematicSvg\" viewBox=\"0 0 800 240\" style=\"width:100%;height:auto;min-width:550px;font-family:var(--mono);\"></svg>\n    </div>\n  </div>\n\n  <!-- MATHEMATICAL & ROOFING DERIVATIONS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1rem;font-family:var(--serif);\">Pitch Multiplier Trigonometry & The 100 Sq Ft \"Square\"</h2>\n    <p style=\"color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1rem;\">\n      In the construction industry, roofing materials are quoted in <strong>Roof Squares</strong>, where $1 \\text{ square} = 100 \\text{ sq ft}$. Because roofs slope upward, the true three-dimensional surface area is always significantly larger than the building's ground footprint.\n    </p>\n\n    <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;font-family:var(--mono);font-size:0.85rem;line-height:1.7;overflow-x:auto;\">\n      <strong>1. Pitch Slope Multiplier ($M$):</strong><br>\n      M = \\frac{\\sqrt{\\text{Rise}^2 + 12^2}}{12} = \\sqrt{1 + \\left(\\frac{\\text{Rise}}{12}\\right)^2}<br>\n      \\textit{Example: For a 6/12 pitch, } M = \\frac{\\sqrt{36 + 144}}{12} = \\frac{\\sqrt{180}}{12} \\approx 1.1180<br><br>\n      <strong>2. Ground Footprint with Overhangs:</strong><br>\n      L_{\\text{gross}} = L_{\\text{house}} + (2 \\times \\text{Overhang}), \\quad W_{\\text{gross}} = W_{\\text{house}} + (2 \\times \\text{Overhang})<br><br>\n      <strong>3. True Surface Area ($A$):</strong><br>\n      A_{\\text{true}} = (L_{\\text{gross}} \\times W_{\\text{gross}}) \\times M \\times (1 + \\frac{\\text{Waste}_{\\%}}{100})<br><br>\n      <strong>4. Roofing Squares & Bundles:</strong><br>\n      \\text{Squares} = \\frac{A_{\\text{true}}}{100}, \\quad \\text{Bundles} = \\lceil \\text{Squares} \\times 3 \\rceil\n    </div>\n  </div>\n\n  <!-- 5 CRITICAL ROOFING TRAPS -->\n  <div style=\"background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:1.75rem;margin-bottom:2.5rem;\">\n    <h2 style=\"font-size:1.35rem;margin-top:0;margin-bottom:1.25rem;font-family:var(--serif);\">5 Critical Roofing & Building Code Pitfalls</h2>\n\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:1.25rem;\">\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">1. Failing the 24\" Ice & Water Shield Code Rule</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          IRC Section R905.1.2 mandates self-adhering ice barrier membrane in snow climates. The code strictly dictates that the membrane must extend from the eave edge to at least 24 inches inside the interior exterior wall line. On wide 24\" soffits, a single 36\" membrane roll leaves an unprotected gap, causing severe ice dam roof leaks.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">2. High-Wind Nailing Under-Fastening</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Standard nailing specifies 4 nails per shingle. However, for high-wind zones (over 110 MPH) or steep pitches ($> 9/12$), building code and manufacturer warranties require a 6-nail pattern with nails placed directly through the double-layer common bond line. Missing the nail line allows winds to blow entire shingle tabs away.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">3. Re-Roofing Over Two Existing Layers</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          IRC Section R908.3.1.1 strictly forbids installing a third layer of asphalt shingles without tearing off existing materials. Three layers of shingles exceed structural dead-load rafter limits (weighing over 700 lbs per square) and prevent new nails from penetrating securely into wood roof decking.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">4. Starving Attic Ventilation (The 1:300 Rule)</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Installing a new roof without matching continuous ridge vents to soffit intake vents bakes shingles from below. Attic temperatures exceeding 150°F cause asphalt oils to volatilize and blister prematurely, voiding manufacturer 30-year warranties within 7 years. Maintain 1 sq ft of Net Free Area (NFA) per 300 sq ft of attic floor.\n        </p>\n      </div>\n\n      <div style=\"background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:1.25rem;\">\n        <h3 style=\"font-size:1rem;margin-top:0;margin-bottom:0.5rem;color:#ef4444;\">5. Closed Valley Shingle Weaving in Heavy Snow</h3>\n        <p style=\"font-size:0.875rem;color:var(--text-muted);line-height:1.5;margin:0;\">\n          Weaving dimensional architectural shingles through valleys creates a thick, bumpy seam that traps melting ice and debris. In northern freeze-thaw zones, open valleys with W-profile 24-gauge prefinished metal flashing shed snow and ice far more effectively and prevent ice dam puncture.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SCRIPT ENGINE -->\n  <script>\n    (function() {\n      function calcRoof() {\n        var len = parseFloat(document.getElementById('roofHouseLen').value) || 0;\n        var wid = parseFloat(document.getElementById('roofHouseWid').value) || 0;\n        var pitchMult = parseFloat(document.getElementById('roofPitch').value) || 1.118;\n        var overhang = parseFloat(document.getElementById('eaveOverhang').value) || 1.0;\n        var wastePct = parseFloat(document.getElementById('roofComplexity').value) || 10;\n\n        var grossLen = len + (2 * overhang);\n        var grossWid = wid + (2 * overhang);\n        var groundSqFt = grossLen * grossWid;\n\n        var trueSlopeSqFt = groundSqFt * pitchMult;\n        var grossWithWaste = trueSlopeSqFt * (1 + (wastePct / 100));\n\n        var squares = grossWithWaste / 100;\n        var bundles = Math.ceil(squares * 3);\n\n        var underlaymentRolls = Math.max(1, Math.ceil(squares / 10)); // 10-square synthetic rolls\n        var perimeterFt = 2 * (grossLen + grossWid);\n        var iceShieldRolls = Math.max(1, Math.ceil(perimeterFt / 65)); // 65 ft rolls\n        var starterBundles = Math.max(1, Math.ceil(perimeterFt / 105)); // ~105 ft per starter bundle\n        var nailsLbs = Math.max(10, Math.ceil(squares * 2.5)); // ~2.5 lbs nails per square\n\n        // Update DOM\n        document.getElementById('shingleBundlesCount').textContent = bundles + ' Bundles';\n        document.getElementById('roofSquaresCount').textContent = squares.toFixed(1) + ' Roof Squares (' + (squares * 100).toFixed(0) + ' sq ft)';\n        document.getElementById('trueRoofAreaSqFt').textContent = Math.round(grossWithWaste).toLocaleString();\n        document.getElementById('groundFootprintLabel').textContent = Math.round(groundSqFt).toLocaleString() + ' sq ft ground footprint';\n\n        document.getElementById('underlaymentRollsVal').textContent = underlaymentRolls + ' Roll' + (underlaymentRolls > 1 ? 's' : '') + ' (10-Sq Synthetic)';\n        document.getElementById('iceWaterShieldVal').textContent = iceShieldRolls + ' Roll' + (iceShieldRolls > 1 ? 's' : '') + ' (36\\\" x 65\\')';\n        document.getElementById('starterStripsVal').textContent = starterBundles + ' Bundle' + (starterBundles > 1 ? 's' : '') + ' (~' + Math.round(perimeterFt) + ' linear ft)';\n        document.getElementById('roofingNailsLbs').textContent = nailsLbs + ' lbs (~' + Math.round(squares * 320).toLocaleString() + ' nails)';\n\n        renderRoofSchematic(pitchMult);\n      }\n\n      function renderRoofSchematic(pitchMult) {\n        var svg = document.getElementById('roofSlopeSchematicSvg');\n        if (!svg) return;\n\n        var svgHtml = '';\n        var startX = 80;\n        var startY = 190;\n        var peakX = 400;\n        var peakY = 50;\n        var rightX = 720;\n\n        // Roof Slope Triangle\n        svgHtml += '<polygon points=\"' + startX + ',' + startY + ' ' + peakX + ',' + peakY + ' ' + rightX + ',' + startY + '\" fill=\"var(--surface)\" stroke=\"#3b82f6\" stroke-width=\"3\"/>';\n\n        // Shingle Layer lines\n        svgHtml += '<line x1=\"' + (startX + 40) + '\" y1=\"' + (startY - 15) + '\" x2=\"' + (rightX - 40) + '\" y2=\"' + (startY - 15) + '\" stroke=\"var(--border)\" stroke-dasharray=\"6,4\"/>';\n\n        // Overhang markers\n        svgHtml += '<text x=\"' + startX + '\" y=\"' + (startY + 25) + '\" fill=\"var(--text-muted)\" font-size=\"11\">Eave Overhang</text>';\n        svgHtml += '<text x=\"' + peakX + '\" y=\"' + (peakY - 12) + '\" fill=\"#3b82f6\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">Ridge Line</text>';\n        svgHtml += '<text x=\"' + rightX + '\" y=\"' + (startY + 25) + '\" fill=\"var(--text-muted)\" font-size=\"11\" text-anchor=\"end\">Eave Overhang</text>';\n\n        // Slope ratio callout\n        svgHtml += '<text x=\"' + (startX + 120) + '\" y=\"' + (startY - 70) + '\" fill=\"#10b981\" font-size=\"12\" font-weight=\"bold\">Pitch Factor: ' + pitchMult.toFixed(3) + 'x</text>';\n\n        svg.innerHTML = svgHtml;\n      }\n\n      function copyRoofTakeoff() {\n        var bundles = document.getElementById('shingleBundlesCount').textContent;\n        var squares = document.getElementById('roofSquaresCount').textContent;\n        var area = document.getElementById('trueRoofAreaSqFt').textContent;\n        var underlay = document.getElementById('underlaymentRollsVal').textContent;\n        var ice = document.getElementById('iceWaterShieldVal').textContent;\n        var starter = document.getElementById('starterStripsVal').textContent;\n        var nails = document.getElementById('roofingNailsLbs').textContent;\n\n        var text = '📋 Roofing Materials Takeoff & Order Sheet\\n' +\n          '• Architectural Shingles: ' + bundles + ' (' + squares + ')\\n' +\n          '• Total Surface Area: ' + area + ' sq ft\\n' +\n          '• Synthetic Underlayment: ' + underlay + '\\n' +\n          '• Ice & Water Shield: ' + ice + '\\n' +\n          '• Starter Strip Shingles: ' + starter + '\\n' +\n          '• Roofing Nails: ' + nails + '\\n\\n' +\n          'Calculated at digitaltoolsshed.com/calc/roofing-shingle-calculator';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyRoofBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '<span>✓ Copied Takeoff!</span>';\n          setTimeout(function() { btn.innerHTML = orig; }, 2000);\n        });\n      }\n\n      var inputs = ['roofHouseLen', 'roofHouseWid', 'roofPitch', 'eaveOverhang', 'roofComplexity'];\n      inputs.forEach(function(id) {\n        var el = document.getElementById(id);\n        if (el) {\n          el.addEventListener('input', calcRoof);\n          el.addEventListener('change', calcRoof);\n        }\n      });\n\n      document.getElementById('copyRoofBtn').addEventListener('click', copyRoofTakeoff);\n\n      calcRoof();\n    })();\n  </script>\n</div>\n";

  writeFileSync(join(calcDir, 'roofing-shingle-calculator.html'), renderPage({
    title: "Roofing Shingle Calculator: Roof Squares, Bundles, Pitch & Waste | Digital Tools Shed",
    metaDesc: "Calculate exact roof squares, shingle bundles (3 per square), synthetic underlayment, starter strips, and nails with roof pitch slope multipliers and IRC code standards.",
    canonical: `${DOMAIN}/calc/roofing-shingle-calculator`,
    bodyContent: roofingBody,
    currentPath: '/calc/roofing-shingle-calculator',
    faq: [
  {
    "q": "How many bundles of shingles are in one square of roofing?",
    "a": "There are exactly 3 bundles of standard architectural (dimensional) or 3-tab shingles in one roof square. One roof square equals 100 square feet of roof surface area."
  },
  {
    "q": "What is roof pitch and how does it change material calculations?",
    "a": "Roof pitch is the vertical rise for every 12 inches of horizontal run (e.g. 6/12 pitch rises 6 inches per foot). Because of the triangle slope, a 6/12 roof has 11.8% more surface area than the flat ground footprint below it; a steep 12/12 pitch has 41.4% more surface area."
  },
  {
    "q": "How many nails do I need per shingle for building code compliance?",
    "a": "Standard installation requires 4 nails per shingle. In designated high-wind hurricane zones (over 110 MPH) or on steep roofs greater than 9/12 pitch, the International Residential Code (IRC) mandates 6 nails per shingle placed precisely through the double-layer nailing line."
  },
  {
    "q": "How much extra shingle waste percentage should I order?",
    "a": "Order 10% extra for a simple gable roof with two flat rectangular planes. Order 15% extra for hip roofs with valleys and ridges, and 20% extra for complex architectural roofs with multiple dormers and turrets."
  },
  {
    "q": "Can I install new asphalt shingles over an old layer of shingles?",
    "a": "Building code allows installing a maximum of two layers of asphalt shingles on a roof. However, tearing off old shingles down to bare plywood is strongly recommended to inspect for rotten wood decking, install fresh Ice & Water Shield, and prevent heavy excess weight that can sag roof rafters."
  }
]
  }));

